export type Raw =
  | { k: 'mc'; p: string; o: string[]; c: number; e: string }
  | { k: 'f'; p: string; a: string; e: string; alt?: string[] }

const m = (p: string, o: [string, string, string, string], c: number, e: string): Raw =>
  ({ k: 'mc', p, o, c, e })
const f = (p: string, a: string, e: string, alt?: string[]): Raw =>
  ({ k: 'f', p, a, e, ...(alt ? { alt } : {}) })

